class Solution {
public:
    int getLengthOfOptimalCompression(string s, int k) {
        int n = s.size();
        auto cost = [](int cnt) -> int {
            if (cnt <= 1) return cnt;
            if (cnt <= 9) return 2;
            if (cnt <= 99) return 3;
            return 4;
        };
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, INT_MAX));
        for (int j = 0; j <= k; j++) dp[n][j] = 0;
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j <= k; j++) {
                if (j > 0) dp[i][j] = dp[i + 1][j - 1];
                int same = 0, diff = 0;
                for (int p = i; p < n; p++) {
                    if (s[p] == s[i]) same++;
                    else diff++;
                    if (diff > j) break;
                    dp[i][j] = min(dp[i][j], cost(same) + dp[p + 1][j - diff]);
                }
            }
        }
        return dp[0][k];
    }
};
